import React, { useState, useEffect, useRef, useCallback } from 'react';
import styles from './Notification.module.css';

function Notification({
                          message,
                          type = 'info',
                          duration = 3000,
                          onClose,
                          showProgress = true
                      }) {
    const [isVisible, setIsVisible] = useState(true);
    const [progress, setProgress] = useState(100);
    const [isPaused, setIsPaused] = useState(false);
    const animationRef = useRef(null);
    const pauseTimeRef = useRef(0);
    const elapsedBeforePauseRef = useRef(0);
    const durationRef = useRef(duration);

    // Обновляем ref при изменении пропса
    useEffect(() => {
        durationRef.current = duration;
    }, [duration]);

    const handleClose = useCallback(() => {
        setIsVisible(false);
        if (onClose) {
            setTimeout(() => onClose(), 300);
        }
    }, [onClose]);

    useEffect(() => {
        if (!isVisible || !showProgress) return;

        let startTime = Date.now();
        let remainingTime = durationRef.current;

        const updateProgress = () => {
            if (isPaused) {
                animationRef.current = requestAnimationFrame(updateProgress);
                return;
            }

            const elapsed = Date.now() - startTime;
            remainingTime = Math.max(0, durationRef.current - elapsed);
            const newProgress = (remainingTime / durationRef.current) * 100;

            setProgress(newProgress);

            if (remainingTime > 0) {
                animationRef.current = requestAnimationFrame(updateProgress);
            } else {
                handleClose();
            }
        };

        animationRef.current = requestAnimationFrame(updateProgress);

        return () => {
            if (animationRef.current) {
                cancelAnimationFrame(animationRef.current);
            }
        };
    }, [isVisible, isPaused, showProgress, handleClose]);

    const handleMouseEnter = () => {
        if (!isPaused) {
            setIsPaused(true);
            pauseTimeRef.current = Date.now();
        }
    };

    const handleMouseLeave = () => {
        if (isPaused) {
            setIsPaused(false);
            const pauseDuration = Date.now() - pauseTimeRef.current;
            // Увеличиваем общее время на время паузы
            durationRef.current += pauseDuration;
        }
    };

    const handleClick = (e) => {
        e.stopPropagation();
        handleClose();
    };

    if (!isVisible) return null;

    return (
        <div
            className={`${styles.notification} ${styles[type]}`}
            onMouseEnter={handleMouseEnter}
            onMouseLeave={handleMouseLeave}
            role="alert"
            aria-live="polite"
        >
            <div className={styles.content}>
                <div className={styles.icon}>
                    {type === 'success' && '✅'}
                    {type === 'error' && '❌'}
                    {type === 'warning' && '⚠️'}
                    {type === 'info' && 'ℹ️'}
                </div>
                <div className={styles.message}>{message}</div>
                <button
                    onClick={handleClick}
                    className={styles.closeBtn}
                    aria-label="Закрыть"
                >
                    ×
                </button>
            </div>

            {showProgress && (
                <div className={styles.progressBar}>
                    <div
                        className={`${styles.progressFill} ${isPaused ? styles.paused : ''}`}
                        style={{
                            width: `${progress}%`,
                            transition: isPaused ? 'none' : 'width 50ms linear'
                        }}
                    />
                    {isPaused && (
                        <div className={styles.pauseIndicator}>⏸️</div>
                    )}
                </div>
            )}
        </div>
    );
}

export default Notification;
